from pathlib import Path
import json, html, textwrap
# Original, illustrative learning examples; not claims about company internals.
LESSONS = [
(233,'Plan before drawing boxes','Design a college canteen app. Students browse menus and place orders; staff prepare them.', 'Functional requirements describe actions. Non-functional requirements describe acceptable latency, availability and data loss. Begin with one API and database; add components only to solve a demonstrated constraint.', 'Assume 10,000 students placing two orders/day over ten hours: 20,000/36,000 = 0.56 orders/second on average. If 20% arrive in a ten-minute rush, peak is 4,000/600 = 6.7/second. Reads may be much higher.', [('Clarify requirements','Ask whether cancellation, payment and offline recovery are required.'),('Estimate demand','Calculate average and peak separately; state assumptions instead of guessing.'),('Define API and data','POST /orders takes item IDs, quantity and an idempotency key. The server computes prices.'),('Start and measure','Use a stateless application and transactional database. Measure bottlenecks before adding caches or queues.')], 'Premature microservices add network failures and deployment work. A design is justified by requirements, not box count.', 'If traffic grows 100 times, which measurement would guide your first change?'),
(234,'Follow a browser request','A student opens GET /orders/42 to see their lunch order.', 'The browser is the client. The server verifies identity and access, applies rules and uses durable storage. The browser should never connect directly to your application database.', 'Knowing an order ID is not permission to see it. The API must verify that order 42 belongs to the authenticated student.', [('Resolve hostname','DNS finds the network address; a cached result can skip a fresh lookup.'),('Connect securely','Establish secure transport. TCP plus TLS is common; HTTP/3 uses QUIC.'),('Authorize and query','Check credentials and order ownership, then query with parameters.'),('Return response','Send JSON and HTTP status; the browser renders it. A timeout leaves the outcome unknown.')], 'UI-only authorization can be bypassed. Correlation IDs help identify where a request spent time.', 'If a response times out but the order exists, should the client create a fresh order?'),
(235,'Understand the front-door components','A shopping page loads a public logo and a private order history.', 'A CDN caches eligible content near users. A reverse proxy fronts upstream servers. A load balancer selects healthy servers. An API gateway adds API policies such as authentication and quotas. One product may perform several roles.', 'A cached logo can return from the CDN without reaching the application. Private history needs authorization and an appropriate private cache policy.', [('Check edge cache','On an eligible cache hit, return immediately; the remaining steps are for forwarded API requests.'),('Apply gateway policy','Validate token and quota. Keep business rules in the application.'),('Balance the request','Choose a healthy backend instance; configure connection and idle timeouts.'),('Enforce object access','The application checks whose order is requested, loads it and returns the response.')], 'Caching private responses publicly leaks data. WebSockets also need long-lived connection routing and a way to locate connected users.', 'Why does gateway token validation not replace order-ownership checks?'),
(236,'Choose storage by access pattern','Orders require a ledger; product discovery requires a searchable index.', 'SQL supports relations and transactional invariants. Key-value stores suit known-key lookups. Documents suit aggregate retrieval. Search engines rank text and support filters. NoSQL products do not all share the same guarantees.', 'Store orders and lines transactionally in PostgreSQL; derive a product search index for queries such as waterproof hiking shoe.', [('Write authoritative data','Commit related order records together; use constraints for uniqueness and valid relationships.'),('Record a change event','For catalog changes, commit an outbox event alongside the product update.'),('Build search view','An idempotent indexer applies versioned changes; replay can rebuild the index.'),('Read the right source','Search the derived index; checkout rechecks authoritative price and stock.')], 'A second store adds synchronization, rebuilds and monitoring. Search can lag behind the source.', 'What happens if search shows a product that just sold out?'),
(237,'Cache a replaceable copy','A waiter remembers the menu but checks the kitchen before promising the last meal.', 'A cache avoids repeated expensive reads. In cache-aside, the application checks cache first, loads the database on a miss and stores a copy with expiry. TTL limits lifetime; it does not promise freshness.', 'Product 42 gets 1,000 reads/minute and two changes/day. Cache its description; final stock and price checks still use authoritative state.', [('Look up product:42','On a permitted fresh-enough hit, return the copy and skip database access.'),('Load only on miss','Query the database. Coalesce simultaneous refreshes for the same key.'),('Store with expiry','Use a TTL and random expiry jitter to spread refresh load.'),('Handle writes','Commit the change then invalidate/update the copy; account for a concurrent stale reader refilling it.')], 'Cache failure can overwhelm the database through fallback. Bound fallback load; consider safe stale reads and version checks.', 'Why can invalidation race with a cache refill?'),
(238,'Separate availability and recovery','A spare counter handles a broken counter; an off-site backup handles a destroyed building.', 'High availability keeps serving during component failures. Disaster recovery restores service after major loss. Replicas provide live copies; backups provide historical recovery. Neither replaces a tested procedure.', 'Assume a recovery-time objective (RTO) of 30 minutes and recovery-point objective (RPO) of five minutes. The first limits downtime; the second limits lost committed data.', [('Detect failure','Health checks remove unhealthy API instances from routing.'),('Protect data','Use suitable database replication plus encrypted recoverable backups and transaction logs.'),('Recover safely','Promote the recovery database and fence the previous writer before switching traffic.'),('Verify recovery','Test real user journeys and measure actual downtime and data loss against objectives.')], 'Async replication may lose recent writes. Replicas also copy accidental deletes, so backups and restore drills remain essential.', 'How would you recover from an accidental delete while every server remains healthy?'),
(239,'Handle disagreement during a partition','Two disconnected ticket counters cannot both safely sell the last seat.', 'During a network partition, a distributed shared-data service cannot always offer both linearizable consistency and a successful response to every request. CAP consistency refers to a single up-to-date logical history, not SQL constraint validity.', 'For three replicas A, B and C, suppose A can reach B but C is isolated. A write requiring two acknowledgements cannot succeed on C alone.', [('Network splits','A and B communicate; C cannot reach them. Define the guarantee required by stock reservations.'),('Require write quorum','With N=3 and W=2, two participating replicas must acknowledge.'),('Read with overlap','R=2 and W=2 overlap for the same replica set because R+W>N; reconcile versions.'),('Handle the minority','Reject or time out operations that cannot meet their contract, then reconcile after connectivity returns.')], 'Quorum overlap alone does not prove linearizability. Version selection, concurrent writers and leader rules matter; sloppy quorums may use different replica sets.', 'Why can a social feed tolerate stale data more easily than last-seat booking?'),
(240,'Control overload','A gate limits arrivals, a bounded queue holds a few people, and backpressure asks upstream to slow down.', 'Rate limiting caps arrivals over time. Throttling reduces or delays work. Backpressure propagates lack of capacity toward producers. Queues absorb short bursts but cannot fix sustained overload.', 'A token bucket with capacity 20 and refill 10 tokens/second allows an idle customer a short burst, then limits the sustained rate.', [('Identify caller','Authenticate and derive the correct tenant/user key; do not trust an arbitrary tenant header.'),('Consume atomically','Refill and consume in one atomic operation; separate reads and writes race.'),('Admit or reject','A token admits work; no token returns HTTP 429 with retry guidance.'),('Bound downstream work','Cap in-flight requests and queue length; signal pressure when consumers cannot keep up.')], 'Five independent per-node quotas can multiply the effective limit. Define fail-open/fail-closed behavior during limiter failure.', 'If five servers each allow 10 requests/second locally, what aggregate rate is possible?'),
(241,'Make one operation safe to retry','A purchase receipt number tells reception that a repeated call refers to the same order.', 'Idempotency means retries of one logical request cause one intended business effect. A durable, concurrency-safe key identifies the operation. An in-memory map on one application instance is not sufficient.', 'Order-request-81 commits, but its response is lost. A retry with the same key should return the original order rather than create another.', [('Send stable key','Generate one key per logical purchase and reuse it only for retries.'),('Claim uniquely','Persist a tenant-scoped key and payload fingerprint under a unique constraint.'),('Commit local effect','Create order and idempotent result in one local transaction; handle concurrent in-progress requests explicitly.'),('Replay or reconcile','Return the stored result. Remote payment requires its own stable provider key and outcome reconciliation.')], 'Reject reuse with a different payload. Define key retention. A local transaction cannot atomically commit a remote card charge.', 'What if identical keys arrive simultaneously at two API instances?'),
(242,'Scale workers versus divide data','More cashiers can share one order book; sharding gives different cashiers different books.', 'Horizontal scaling adds service instances. Partitioning splits a dataset. Sharding puts partitions on independently operated database nodes. Replication copies the same data. More API instances do not automatically increase database write capacity.', 'Partition chat messages by conversation ID so one conversation can be read without querying every shard.', [('Scale stateless APIs','A load balancer sends requests to multiple instances; persistent state remains external.'),('Choose partition key','Conversation ID keeps typical message queries within one partition.'),('Route ownership','A routing map or hash identifies the shard owning that conversation.'),('Rebalance carefully','Move partitions with explicit ownership/version rules; monitor hot conversations.')], 'A celebrity group can overload a shard. Cross-shard transactions, global ordering and migrations add complexity.', 'Why can sharding by country leave one database overloaded?'),
]
LESSONS += [
(243,'Build a short-link service','A code is a coat-check ticket pointing to something stored elsewhere.', 'A shortener stores code-to-URL mappings. Creation writes the mapping; opening a code reads it and returns an HTTP redirect. The browser then follows the Location header.', 'POST /links stores aB72 mapped to https://example.test/products/42. GET /aB72 returns 302 and that target if the link is active.', [('Create mapping','Validate URL scheme and permissions, generate a code and insert it under a unique constraint.'),('Receive redirect','Check a cache for the code; only on a miss read the mapping database.'),('Check link policy','Apply expiration, disabled status and abuse policy. Missing links return 404; expiration can use a documented 410 policy.'),('Return Location','Send the redirect; record analytics asynchronously so analytics failure does not block navigation.')], 'Permanent redirects may remain cached after target changes. Choose status and cache policy deliberately. Block dangerous schemes and provide takedowns.', 'Which is more important to preserve: one click metric or the code-to-URL mapping?'),
(244,'Generate unique codes','Sequential tickets need a unique allocator; random tickets need a collision check.', 'Base62 encodes numbers with 62 symbols; it does not generate uniqueness. Encode an allocated unique ID, or generate random codes and enforce uniqueness on insertion.', 'Seven Base62 characters offer 62^7 = 3,521,614,606,208 possibilities. Birthday collisions are still possible when drawing many random codes.', [('Choose strategy','A database sequence is simple; random codes can reduce easy enumeration.'),('Build candidate','Encode the allocated ID or draw random characters; define case sensitivity.'),('Insert uniquely','Use the unique index as the arbiter. Checking existence before insertion alone races.'),('Retry collisions','Generate another random candidate with bounded retries; never overwrite an existing mapping.')], 'Sequential codes expose ordering. Random codes are not authorization. Distributed timestamp IDs need worker IDs and clock-regression handling.', 'Why is Base62(123) unique only when 123 was allocated uniquely?'),
(245,'Handle a viral link','Repeatedly reading a popular ticket should not repeatedly open the archive.', 'Redirects usually outnumber creations. Cache active mappings and add stateless redirect instances. A viral code is a hot key even if all other keys are evenly distributed.', 'An illustrative 100M redirects/day averages 1,157/second. A tenfold peak is 11,574/second. Even 99% cache hits leave about 116 database reads/second at peak.', [('Receive hot request','Edge or redirect API receives /sale42 under a cache policy compatible with mutability.'),('Read cached mapping','Return a permitted cache hit; bounded local caches can reduce shared hot-key traffic.'),('Coalesce miss','Only a miss triggers database reload; one refresher serves many waiting readers.'),('Separate analytics','Emit bounded asynchronous metrics; decide explicitly whether to buffer or drop during failure.')], 'Cache outage exposes full traffic to the database. Bound fallback load and takedown propagation time; test the failure path.', 'How quickly must a disabled phishing link stop working across caches?'),
(246,'Store a message before acknowledging it','A postal office accepting a letter and delivering it are separate events.', 'Chat combines live connections with durable history. A server acknowledgement means accepted under a defined durability contract. Delivery and read receipts are separate states.', 'Alice sends m81 while Bob is offline. Alice sees accepted after commit. Bob later reconnects with his last-seen cursor and fetches missing messages.', [('Send stable message ID','Send conversation ID, client message ID and content over an authenticated connection.'),('Persist before ack','Authorize membership, deduplicate the ID and commit message plus delivery event.'),('Attempt live delivery','Find Bob’s active connection and push if present; offline messages stay in durable history.'),('Recover on reconnect','Bob fetches after his cursor, acknowledges delivery and may separately send a read receipt.')], 'A WebSocket is not durable storage. Push notifications are wake-up hints. Lost acknowledgements cause retries and duplicate delivery attempts.', 'What should accepted mean if Bob has no active connection?'),
(247,'Order messages and remove duplicates','Numbered pages stay readable when the printer hands you the same page twice.', 'Retries and reconnects can duplicate or reorder delivery. Use a stable client message ID for deduplication and an authoritative per-conversation sequence for accepted order.', 'm81 gets sequence 41 but Alice loses the response. Retrying must return 41. Bob receiving 42 before 41 can detect a gap and fetch missing history.', [('Accept stable ID','Use an appropriate conversation/sender/client-ID unique key bound to the original payload.'),('Assign sequence','A partition owner or transactional sequencer assigns conversation order at commit.'),('Deliver with retries','Bob deduplicates already-applied IDs and buffers or fetches missing ranges.'),('Resume from cursor','Reconnect requests messages after a durable cursor, independent of the old socket.')], 'Conversation order is not global order. Huge groups can overload one ordering owner. Tombstones distinguish intentional deletion from a delivery gap.', 'Why is a phone timestamp unreliable as the only ordering key?'),
(248,'Deliver to a group and track presence','A group announcement has many recipients; an attendance light is only a recent hint.', 'Fan-out-on-write prepares individual deliveries; fan-out-on-read fetches shared history. Presence is usually approximate, based on heartbeats and expiry rather than a guaranteed disconnect notification.', 'A 50-member study group can use per-member delivery tasks. A 100,000-member announcement channel may prefer shared history and cursor reads.', [('Check membership','Authorize the sender and define membership/version rules for recipients.'),('Commit once','Persist group message and delivery event in one local transaction.'),('Fan out asynchronously','Workers push to eligible devices; very large groups may fetch shared history instead.'),('Expire presence','Heartbeats refresh TTLs; stale sessions disappear without blocking durable message delivery.')], 'Joining/leaving affects history access and in-flight delivery. Each device needs a cursor. Broadcasting every presence change to a huge group can dominate load.', 'May a departed member read a message sent after leaving?'),
(249,'Encrypt at the endpoints','The server carries a locked parcel; only authorized devices can open it.', 'End-to-end encryption keeps content encryption/decryption on endpoint devices. TLS protects a connection to the server but can still expose plaintext at that server. Use established audited protocols.', 'Alice encrypts for Bob’s authorized devices before upload. The server queues ciphertext for offline delivery and cannot directly run plaintext search over it.', [('Authenticate device keys','The protocol verifies recipient device keys; enrollment and key-change verification matter.'),('Encrypt on sender','Alice’s device produces encrypted envelopes before sending to the service.'),('Store and route ciphertext','The service forwards envelopes; routing metadata such as recipients and timing can remain visible.'),('Decrypt on recipient','Bob’s devices decrypt locally; backups and lost-device recovery need explicit key management.')], 'Server-side moderation and search change. Reports can deliberately disclose selected messages. Weak backups and compromised endpoints can defeat confidentiality.', 'Why does HTTPS alone not provide Alice-to-Bob end-to-end encryption?'),
(250,'Separate browsing and checkout','Browsing uses a catalog copy; buying the last item needs the real stock ledger.', 'Catalog, cart, checkout, payment and fulfillment have different correctness needs. A cart records intent, not a permanent promise of price or availability.', 'A buyer adds two mugs. One sells out and the price changes before checkout. The server must recompute current terms rather than trust browser totals.', [('Browse','Caches and search serve descriptions and estimated availability.'),('Build cart','Store item IDs and quantities under the authenticated customer; validate limits and ownership.'),('Validate checkout','Recompute authoritative price, reserve inventory and create an idempotent pending order.'),('Complete workflow','Verify payment results, transition durable order state and schedule fulfillment.')], 'Long synchronous chains increase timeout exposure. A modular monolith is a useful starting point; separate services when ownership or scaling justifies them.', 'Why must the server reject a client-supplied discounted total?'),
(251,'Reserve the last unit atomically','Two cashiers must not both promise the same last mug.', 'A separate read of available=1 followed by a write lets competing buyers both decide to sell. Reserve with an atomic condition or equivalent serialization at the authoritative data boundary.', 'Buyers A and B request the final unit. A guarded database update lets only one committed transaction decrement available from 1 to 0.', [('Begin reservation','Identify the idempotent reservation and pending order.'),('Update conditionally','UPDATE inventory SET available=available-1 WHERE sku=:sku AND available>=1 RETURNING available; inspect whether a row was returned.'),('Commit together','Record reservation and stock change in one transaction; rollback the entire attempt if a required condition fails.'),('Expire with guards','Release abandoned reservations through a guarded state transition so expiry cannot release stock twice.')], 'Hot rows serialize and create waiting. Keep transactions short and cap admission. Never hold the stock row lock while calling a payment provider.', 'What response should buyer B receive after buyer A commits?'),
(252,'Recover checkout after partial failure','Stock reservation and card payment are separate promises; a timeout undoes neither.', 'A saga records workflow progress across local transactions and external effects. A compensation is a new action such as refunding a charge; it does not erase history.', 'A provider charges the card but its response times out. Keep the result unknown/pending and reconcile using the original provider key; a fresh key can double-charge.', [('Record intent','Commit pending order, reservation and payment-request outbox event together when they share a database.'),('Request payment','A worker calls the provider with a stable idempotency key outside the database transaction.'),('Verify outcome','Authenticate callbacks, deduplicate provider event IDs and query the provider for unknown outcomes.'),('Transition once','Guard order-state changes; confirm and fulfill, or release/refund according to recorded outcome and policy.')], 'Callbacks may be delayed, duplicated or out of order. A success after stock expiry requires a policy such as reacquisition or refund.', 'Why is unknown more accurate than failed after a payment timeout?'),
(253,'Commit a business change and event together','Write the order and the instruction to announce it on the same durable page.', 'Transactional outbox stores the business update and an event in one database transaction. A relay publishes committed rows later, closing the crash window between database commit and event publish.', 'Order 81 becomes confirmed alongside outbox event e81. An API crash after commit cannot erase the event the relay must publish.', [('Commit both','Update the order and insert e81 with event ID and aggregate version in one transaction.'),('Relay committed rows','A poller or change-data-capture reader publishes to the broker.'),('Record publication progress','Mark progress after broker acknowledgement; a crash before marking can republish.'),('Deduplicate consumer','Commit consumer effect and processed event ID atomically, or use an idempotent state transition.')], 'Delivery is normally at least once, not automatic exactly once. Monitor oldest outbox age and preserve per-aggregate ordering when needed.', 'Which crash window causes duplicate publication?'),
(254,'Design discovery as a derived view','The shop directory finds a shelf; the cashier verifies the purchase terms.', 'Text search ranks matching documents; filters restrict exact attributes; recommendations rank candidates using context. Search indexes are derived and may lag behind authoritative catalog changes.', 'Search running shoes with size 9 and relevance sorting. Recommendations suggest socks; checkout independently revalidates stock, price and eligibility.', [('Change catalog','Commit product attributes and a versioned source event.'),('Update index','Apply newer versions and tombstones idempotently; support rebuilding from history or snapshots.'),('Search and rank','Apply text query, filters, pagination and visibility rules before returning eligible candidates.'),('Recheck purchase','Use authoritative state for checkout instead of trusting the search copy.')], 'Provide a default ranking for new users and a fallback if recommendations fail. Monitor index lag; stable cursor pagination may suit changing results.', 'What should users still be able to do when recommendations are down?'),
]
LESSONS += [
(255,'Match a rider and run a trip','Dispatch finds candidates, offers a trip and allows exactly one valid assignment.', 'Driver location is fast-changing and approximate. A confirmed assignment and trip lifecycle need stronger durable correctness. Separate these two kinds of state.', 'A rider requests pickup near a station. Nearby available drivers are shortlisted, ranked by pickup time and offered the ride with an acceptance deadline.', [('Request ride','Authenticate and create one pending trip under an idempotency key.'),('Find candidates','Read fresh nearby positions and estimate pickup times.'),('Offer and claim','Use bounded offers; acceptance must atomically prevent rider/driver double-assignment.'),('Run lifecycle','Persist accepted, arrived, started and completed states; publish updates and coordinate payment.')], 'Location can be stale or spoofed. Recheck availability when claiming, not just when searching. Reconnects recover durable trip state.', 'If a geographic index says free but the trip database says busy, which wins?'),
(256,'Find drivers near a pickup','Search nearby map cells first, then compare actual road travel.', 'Spatial indexes narrow coordinate searches without scanning the whole fleet. Cells, geohashes and spatial database indexes are options. Straight-line distance is only a candidate filter.', 'The closest driver is across a river. A slightly farther driver on the same side may reach the rider sooner.', [('Update position','Store driver ID, coordinates, timestamp and availability hint; expire stale observations.'),('Search neighboring cells','Include boundary neighbors and expand the radius if there are too few candidates.'),('Filter shortlist','Reject stale, incompatible or unavailable drivers before expensive route calculations.'),('Rank by travel ETA','Compute route-based estimates for a bounded shortlist; matching still claims atomically.')], 'Small cells create many neighbor queries; large cells scan many drivers. GPS jitter and high update rates need thresholds and expiry.', 'Why does searching only the rider’s own cell miss some nearby drivers?'),
(257,'Make assignment a guarded transition','Two dispatchers may propose the same driver, but only one claim should win.', 'A state machine lists allowed transitions. Compare-and-set or a transaction checks the expected state/version before writing. Lock expiry alone cannot prevent an old holder writing stale state.', 'Two riders compete for driver D7. In one database, a conditional transition from available to reserved can succeed for only one transaction.', [('Read expected state','Identify pending trip T81 and driver D7; this snapshot does not guarantee later availability.'),('Claim atomically','In one local transaction when possible, claim the available driver and accept the pending trip; rollback if either condition fails.'),('Publish after commit','Commit an outbox event before telling clients the assignment is confirmed.'),('Reject late actions','Check expected state/version for acceptance or cancellation; return current state for stale requests.')], 'Separate shards cannot share a normal local transaction. Use an assignment owner or recoverable reservation protocol with fencing rather than assuming global atomicity.', 'How should an acceptance arriving after offer expiry be handled?'),
(258,'Distinguish an ETA from a price promise','An arrival time is a forecast; a quote has agreed terms and an expiry.', 'ETA estimates travel from routes, traffic and pickup conditions. Surge responds to recent demand/supply under a defined pricing policy. Inputs need freshness, smoothing and fallback behavior.', 'An illustrative area sees 100 requests and 20 available drivers in a recent window. That signal may inform pricing, but does not by itself define a trustworthy multiplier.', [('Collect signals','Aggregate demand, supply and travel observations by area/window; detect stale inputs.'),('Estimate pickup','Route a shortlist and communicate uncertainty instead of a guaranteed arrival second.'),('Store quote','Apply a bounded, versioned policy and store quote ID, currency, terms and expiry.'),('Bind accepted terms','Accept an unexpired quote against its recorded terms; define any final-fare adjustment separately.')], 'Rapid feedback can cause oscillating prices. Define pricing and ETA fallback when data is unavailable and monitor prediction error.', 'What should happen if the quote expires while the rider decides?'),
]

def build():
 root=Path(__file__).resolve().parents[1]
 assets=root/'docs/system-design/diagrams';assets.mkdir(exist_ok=True)
 qs=json.loads((root/'data/questions.json').read_text(encoding='utf-8'))
 for ident,title,analogy,concept,scenario,steps,failure,check in LESSONS:
  q=next(q for q in qs if q['id']==ident)
  q.update(explanation=concept,why=analogy,example=scenario,tradeoffs=failure,detailStatus='Expanded',learningTitle=title,walkthroughSteps=[{'title':t,'explanation':d} for t,d in steps],knowledgeCheck=check,diagramImage=f'docs/system-design/diagrams/topic-{ident}.svg')
  q['diagram']=' → '.join(t for t,d in steps)
  esc=html.escape
  parts=[f'<svg xmlns="http://www.w3.org/2000/svg" width="960" height="960" viewBox="0 0 960 960" role="img" aria-labelledby="title desc"><title id="title">{esc(title)}</title><desc id="desc">{esc(q["diagram"])}. Illustrative sequence; conditions are explained in the steps.</desc>', '<defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L8,3 L0,6" fill="#38bdf8"/></marker></defs>','<rect width="960" height="960" rx="18" fill="#0f172a"/>',f'<text x="40" y="48" fill="#f8fafc" font-family="Arial,sans-serif" font-size="25" font-weight="bold">{ident}. {esc(title)}</text>', '<text x="40" y="80" fill="#cbd5e1" font-family="Arial,sans-serif" font-size="16">Illustrative flow • follow steps 1–4 and check the conditions on each step</text>']
  for i,(label,detail) in enumerate(steps):
   y=110+i*168
   parts.extend([f'<rect x="40" y="{y}" width="880" height="142" rx="12" fill="#1e293b" stroke="#38bdf8"/>',f'<text x="60" y="{y+30}" fill="#7dd3fc" font-family="Arial,sans-serif" font-size="21" font-weight="bold">{i+1}. {esc(label)}</text>'])
   for j,line in enumerate(textwrap.wrap(detail,92,break_long_words=False,break_on_hyphens=False)):parts.append(f'<text x="60" y="{y+60+j*22}" fill="#f1f5f9" font-family="Arial,sans-serif" font-size="17">{esc(line)}</text>')
   if i<3:parts.append(f'<path d="M480,{y+144} L480,{y+165}" stroke="#38bdf8" stroke-width="3" marker-end="url(#arrow)"/>')
  parts.append('<text x="40" y="818" fill="#fbbf24" font-family="Arial,sans-serif" font-size="19" font-weight="bold">Failure / trade-off to explain</text>')
  for j,line in enumerate(textwrap.wrap(failure,101,break_long_words=False)):parts.append(f'<text x="40" y="{848+j*21}" fill="#e2e8f0" font-family="Arial,sans-serif" font-size="16">{esc(line)}</text>')
  parts.append('</svg>');(assets/f'topic-{ident}.svg').write_text('\n'.join(parts),encoding='utf-8')
 (root/'data/questions.json').write_text(json.dumps(qs,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 for slug,start,end in [('foundations',233,242),('url-shortener',243,245),('whatsapp-messaging',246,249),('e-commerce-payments',250,254),('uber-ride-hailing',255,258)]:
  selected=[q for q in qs if start<=q['id']<=end];out=[f'# {selected[0]["category"]}\n','Read the example, follow the flow, then explain the failure case. These are illustrative designs, not documented company internals.\n','[Beginner guide and glossary](system-design/visual-learning-guide.md) · [Case studies](system-design/README.md)\n']
  for q in selected:
   out += [f'## {q["id"]}. {q["question"]}\n',f'### {q["learningTitle"]}\n',q['why']+'\n','### What it means\n',q['explanation']+'\n','### Worked real-world example\n',q['example']+'\n',f'![{q["learningTitle"]}](system-design/diagrams/topic-{q["id"]}.svg)\n','### Follow the flow\n']
   out += [f'{i}. **{step["title"]}:** {step["explanation"]}\n' for i,step in enumerate(q['walkthroughSteps'],1)]
   out += ['### Failure and trade-offs\n',q['tradeoffs']+'\n','### Check your understanding\n',q['knowledgeCheck']+'\n']
  (root/f'docs/system-design-{slug}.md').write_text('\n'.join(out),encoding='utf-8')
 print('Expanded 26 lessons with matching SVG diagrams and Markdown guides.')

if __name__=='__main__':build()
